  "scenario_id": "sc-2d248f",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "empirical A/E SD ~0.38 vs Poisson expectation ~0.027; swings up to ±0.65 from baseline",
      "confidence": 0.95,
      "evidence": [
        "ae_ip_by_year.csv shows extreme year-to-year swings (0.41 to 1.65) without gradual buildup",
        "empirical SD (~0.38) is ~14x larger than Poisson null (~1/sqrt(E)), invalidating per-year z-scores",
        "ae_ip_termination.csv shows diagnosis-level recovery A/E within 0.95–1.04, ruling out a diagnosis-specific recovery shift"
      ],
      "recommended_action": "Investigate IP claims/exposure data quality and external drivers for 2015/2016/2020 spikes; adopt overdispersed credibility model (e.g., Negative Binomial) for projection; exclude structural outliers from trend fitting; review pricing/valuation assumptions for tail risk."
    }
  ]
}

